def build_sp_ntl_from_list(data_list):
	result = {}
	for entry in data_list:
		es_list = entry.get('es', [])
		ntl = entry.get('ntl')
		for word in es_list:
			result[word] = ntl
	return result

sp_ntl.update(build_sp_ntl_from_list(sp_ntl_list))